from fastapi import APIRouter, Request
from fastapi.responses import JSONResponse

logger = logging.getLogger(__name__)
router = APIRouter(prefix="/health", tags=["health"])


@router.get("/live")
def live() -> dict[str, str]:
    """Process liveness; deliberately independent of PostgreSQL and S3."""
    return {"status": "ok"}


@router.get("/ready")
def ready(request: Request) -> JSONResponse:
    checks = {}
    for name, dependency in (
        ("database", request.app.state.database),
        ("storage", request.app.state.storage),
    ):
        try:
            dependency.check_ready()
            checks[name] = "ok"
        except Exception:
            # Driver exception messages may contain DSNs, keys or request headers.
            logger.warning("Readiness dependency failed: %s", name)
            checks[name] = "error"
    healthy = all(value == "ok" for value in checks.values())
    return JSONResponse(
        status_code=200 if healthy else 503,
        content={"status": "ok" if healthy else "not_ready", "checks": checks},
    )
from sqlalchemy import create_engine, text
from sqlalchemy.orm import sessionmaker

from app.core.config import Settings


class Database:
    def __init__(self, settings: Settings) -> None:
        self.engine = create_engine(
            settings.database_url,
            pool_pre_ping=True,
            pool_size=5,
            max_overflow=5,
            connect_args={"connect_timeout": 3},
        )
        self.session_factory = sessionmaker(
            bind=self.engine, autoflush=False, expire_on_commit=False
        )

    def check_ready(self) -> None:
        with self.engine.connect() as connection:
            connection.execute(text("SELECT 1"))
            if not connection.execute(text("SELECT version_num FROM alembic_version")).first():
                raise RuntimeError("Database migrations have not been applied")

    def close(self) -> None:
        self.engine.dispose()

